import { LRUCache } from 'lru-cache';
import { createClient } from 'redis';

const redis = createClient({
  url: process.env.REDIS_URL,
  disableOfflineQueue: true, // fail fast while disconnected instead of queueing
  socket: { connectTimeout: 2_000 },
});
redis.on('error', (err) => console.warn('redis', err.message)); // unhandled 'error' crashes Node
redis.connect().catch(() => {}); // start without Redis; the client keeps reconnecting

// L1: per pod, short TTL, hard size limit
const l1 = new LRUCache<string, string>({ max: 5_000, ttl: 5_000 });

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  let timer: NodeJS.Timeout | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error('cache timeout')), ms);
  });
  return Promise.race([p, timeout]).finally(() => clearTimeout(timer));
}

export async function cached<T>(key: string, ttlSec: number, load: () => Promise<T>): Promise<T> {
  const hit1 = l1.get(key);
  if (hit1 !== undefined) return JSON.parse(hit1) as T;

  try {
    const hit2 = await withTimeout(redis.get(key), 50);
    if (hit2 !== null) { l1.set(key, hit2); return JSON.parse(hit2) as T; }
  } catch (err) {
    console.warn('cache read skipped', (err as Error).message); // fall through to the source
  }

  const value = await load();
  const json = JSON.stringify(value);
  l1.set(key, json);
  redis.set(key, json, { EX: ttlSec }).catch(() => {}); // never fail a request on a cache write
  return value;
}

const cache = new Map<string, Report>();

export async function getReport(userId: string, from: string, to: string) {
  const key = `${userId}:${from}:${to}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const report = await buildReport(userId, from, to);
  cache.set(key, report);
  return report;
}

