# Hashed build output: safe to cache forever.
# ^~ matters: without it the regex block below would win for /assets/*.svg
location ^~ /assets/ {
    add_header Cache-Control "public, max-age=31536000, immutable";
    try_files $uri =404;
}

# Unhashed public files: cache briefly, then revalidate
location ~* \.(png|svg|ico|webmanifest)$ {
    add_header Cache-Control "public, max-age=3600";
}

# HTML entry point: always revalidate (nginx sends an ETag for static files by default)
location / {
    add_header Cache-Control "no-cache";
    try_files $uri /index.html;
}

# Personal API data: never store anywhere
location /api/me {
    add_header Cache-Control "private, no-store" always;
    proxy_pass http://app;
}

location /assets/ {
    add_header Cache-Control "public, max-age=31536000, immutable";
}

