import { createClient } from 'redis';

const redis = createClient({
  url: process.env.REDIS_URL,
  socket: { connectTimeout: 2_000 },
});
redis.on('error', (err) => console.error('redis', err)); // without this, errors crash the process
await redis.connect();

const LIMIT = 100;   // requests
const WINDOW = 60;   // seconds

export async function allow(userId: string): Promise<boolean> {
  const windowStart = Math.floor(Date.now() / 1000 / WINDOW);
  const key = `rl:${userId}:${windowStart}`;

  const [count] = await redis
    .multi()
    .incr(key)              // atomic: no read-then-write race
    .expire(key, WINDOW * 2) // old windows clean themselves up
    .exec();

  return Number(count) <= LIMIT;
}

