import { randomUUID } from 'node:crypto';
import { createClient } from 'redis';

const redis = createClient({ url: process.env.REDIS_URL });
redis.on('error', (err) => console.warn('redis', err.message));
await redis.connect();

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const jitter = (sec: number) => Math.round(sec * (0.9 + Math.random() * 0.2));
// Delete the lock only if we still own it (atomic in Redis)
const RELEASE = "if redis.call('GET', KEYS[1]) == ARGV[1] then return redis.call('DEL', KEYS[1]) end return 0";

export async function getOrLoad<T>(key: string, ttlSec: number, load: () => Promise<T>): Promise<T> {
  const lockKey = `lock:${key}`;
  for (let attempt = 0; attempt < 3; attempt++) {
    const hit = await redis.get(key);
    if (hit !== null) return JSON.parse(hit) as T;

    const token = randomUUID();
    const gotLock = await redis.set(lockKey, token, { NX: true, PX: 10_000 });
    if (gotLock) {
      try {
        const value = await load();
        await redis.set(key, JSON.stringify(value), { EX: jitter(ttlSec) });
        return value;
      } finally {
        await redis.eval(RELEASE, { keys: [lockKey], arguments: [token] });
      }
    }
    await sleep(100); // others wait briefly, then re-check the cache
  }
  return load(); // give up waiting rather than fail the request
}

