import { onCLS, onINP, onLCP, type MetricWithAttribution } from 'web-vitals/attribution';

// Which element caused the score: the LCP element, the clicked element, the shifted element
function targetOf(m: MetricWithAttribution): string | undefined {
  switch (m.name) {
    case 'LCP': return m.attribution.target;
    case 'INP': return m.attribution.interactionTarget;
    case 'CLS': return m.attribution.largestShiftTarget;
    default: return undefined;
  }
}

function send(metric: MetricWithAttribution) {
  const body = JSON.stringify({
    name: metric.name,          // 'LCP' | 'INP' | 'CLS'
    value: metric.value,
    rating: metric.rating,      // 'good' | 'needs-improvement' | 'poor'
    id: metric.id,
    page: location.pathname,
    target: targetOf(metric),
  });
  // sendBeacon survives the page being closed or hidden
  if (!navigator.sendBeacon('/rum', body)) {
    fetch('/rum', { method: 'POST', body, keepalive: true }).catch(() => {});
  }
}

onLCP(send);
onINP(send);
onCLS(send);

